//*****************************************************************************
// App callbacks
//*****************************************************************************
static uint32_t s_lastTick;
             // end of the previous frame (for the frame cap)
static uint32_t s_lastUpd;
              // time of the previous update
static uint32_t s_owed;


static void PaceInit(void)
{
    s_lastTick = TimerNow();
    s_lastUpd  = s_lastTick;
    s_owed     = 0;
}


// Busy-wait until one frame period has passed since the previous frame ended.
// The counter counts DOWN, so elapsed = last - now (wrap-safe in uint32).
static void PaceWait(void)
{
    while((uint32_t)(s_lastTick - TimerNow()) < RC_FRAME_TICKS) { }
    s_lastTick = TimerNow();
}


// The game simulates at a fixed 30 ticks per second no matter how long drawing
// took: if a frame was slow, the missing ticks are run now (up to
// RC_MAX_CATCHUP), so walking speed, cooldowns and enemy speed stay in real
// time instead of slowing down with the frame rate.
static uint16_t TicksOwed(void)
{
    uint32_t now = TimerNow();
    uint16_t n   = 0;

    s_owed   += (uint32_t)(s_lastUpd - now);
    s_lastUpd = now;

    while(s_owed >= RC_FRAME_TICKS && n < RC_MAX_CATCHUP)
    {
        s_owed -= RC_FRAME_TICKS;
        n++;
    }
    if(s_owed > RC_FRAME_TICKS) s_owed = RC_FRAME_TICKS;    // too far behind: let go
    if(n == 0) { n = 1; s_owed = 0; }                       // always make progress
    return n;
}


// ---- The dungeon music ---------------------------------------------------------
// Wave 1 plays the buzzer theme; from RC_THEME_ROUND on, /MP3/0010.mp3 on the MP3
// module's SD card takes over and repeats. The module's own "loop" command (0x08)
// counts files in card order instead of using /MP3/0010.mp3, so it is NOT used:
// we play the file by name and restart it when it ends. "It ended" is seen two ways,
// because some DFPlayer clones never send the "track done" message:
//   1. the module's track-done message (MP3_trackFinished), or
//   2. every RC_THEME_CHECK frames we ask the module "are you playing?" (query 0x42)
//      and restart if the answer is "stopped".
#define RC_THEME_TRACK   10      // /MP3/0010.mp3
#define RC_THEME_ROUND   2       // the wave the MP3 takes over (1 = from the start)
#define RC_THEME_CHECK   90      // frames between "are you playing?" queries (3 s)
#define MP3_Q_STATUS     0x42    // DFPlayer status query; reply low byte 0 = stopped

static bool     s_rcThemeOn;     // the MP3 track has taken over
static uint16_t s_rcThemeChk;    // frames to the next status query

static void RcTheme_Start(void)
{
    Buzzer_Stop();               // the buzzer theme (and any sfx) yields to the MP3
    MP3_playTrack(RC_THEME_TRACK);
    s_rcThemeOn  = true;
    s_rcThemeChk = RC_THEME_CHECK;
}

// Once per frame: hand over to the MP3 at RC_THEME_ROUND, then keep it looping.
static void RcTheme_Update(void)
{
    if(!s_rcThemeOn)
    {
        if(rc_wave >= RC_THEME_ROUND && rc_mode == MODE_PLAY) RcTheme_Start();
        return;
    }
    MP3_poll();                                             // read the module's messages
    if(MP3_trackFinished()) { RcTheme_Start(); return; }
    if(--s_rcThemeChk) return;
    s_rcThemeChk = RC_THEME_CHECK;
    if(MP3_getLastCmd() == MP3_Q_STATUS && (MP3_getLastParam() & 0xFFu) == 0u)
        RcTheme_Start();                                    // last answer: "stopped"
    else
        MP3_sendCommand(MP3_Q_STATUS, 0, 0);                // ask again; answer next check
}


static void RC_Init(void)
{
    uint16_t i;

    PaceInit();
    rc_BuildTables();
    rc_ResetRun();
    for(i = 0; i < RC_MAX_ENEMIES; i++) rc_en[i].alive = 0;
    for(i = 0; i < RC_MAX_OBJ; i++)     rc_obj[i].alive = 0;
    rc_stX = rc_stY = 0;
    rc_hud = 0;
    rc_LoadScores();
    rc_StartLevel();

    s_rcThemeOn = false;                       // new run: buzzer theme first
    MP3_stop();
    rc_EnterTitle();                           // title screen first; the music starts when you enter
}


static AppStatus RC_Update(void)
{
    uint16_t n, i;

    RcTheme_Update();

    switch(rc_mode)
    {
        case MODE_TITLE:
        case MODE_HOWTO:
        case MODE_LETTER:
            n = TicksOwed();
            if(rc_UpdateTitle(n))                    // letter dismissed: into the dungeon
            {
                rc_mode      = MODE_INTRO;
                rc_timer     = 75;
                rc_banner    = BAN_LEVEL;
                rc_dirtyFull = true;
                Buzzer_PlaySong(&song_corridor_run, 1);      // the dungeon theme (MP3 from RC_THEME_ROUND)
            }
            break;

        case MODE_INTRO:
            n = TicksOwed();
            rc_timer = (rc_timer > n) ? (uint16_t)(rc_timer - n) : 0;
            if(rc_timer == 0)
            {
                rc_mode       = MODE_PLAY;
                rc_invalidate = true;            // wipes the banner
                rc_viewDirty  = 2;
            }
            break;

        case MODE_PLAY:
            n = TicksOwed();
            for(i = 0; i < n && rc_mode == MODE_PLAY; i++)
            {
                rc_UpdatePlay();
                g_dpad.uPressed = g_dpad.dPressed = 0;      // button edges count once,
                g_dpad.lPressed = g_dpad.rPressed = 0;      // not once per catch-up tick
                g_joy.btnPressed = 0;
            }
            if(rc_lvPending && rc_mode == MODE_PLAY) rc_EnterCards(CS_LEVEL);
            break;

        case MODE_INV:                          // inventory / vendor / swap list: the game is paused
            rc_UpdateInventory();
            s_lastUpd = TimerNow();
            s_owed    = 0;
            break;

        case MODE_CARDS:
            rc_UpdateCards();
            s_lastUpd = TimerNow();             // time spent choosing is not owed to the game
            s_owed    = 0;
            break;

        case MODE_CLEAR:
            n = TicksOwed();
            rc_timer = (rc_timer > n) ? (uint16_t)(rc_timer - n) : 0;
            if(rc_timer == 0)
            {
                rc_mode       = MODE_PLAY;
                rc_invalidate = true;            // wipes the banner
                rc_viewDirty  = 2;
                if(rc_lvPending) rc_EnterCards(CS_LEVEL);
            }
            break;

        default:                                // game over, name entry, high scores
            if(rc_UpdateOverScreens()) return APP_QUIT;
            s_lastUpd = TimerNow();
            s_owed    = 0;
            break;
    }

    return APP_CONTINUE;
}


static void FullRepaint(void)
{
    if(rc_mode == MODE_TITLE || rc_mode == MODE_HOWTO || rc_mode == MODE_LETTER)
        rc_DrawTitleFull();
    else if(rc_mode == MODE_CARDS)
        rc_DrawCardsFull();
    else if(rc_mode == MODE_INV)
        rc_DrawInventoryFull();
    else if(rc_mode == MODE_OVER || rc_mode == MODE_NAME || rc_mode == MODE_SCORES)
        rc_DrawEndScreen();
    else
    {
        rc_DrawHudFrame();
        rc_hud        = HUD_ALL;
        rc_invalidate = true;
        rc_viewDirty  = 2;
        rc_cdShown    = -1;
        rc_manaShown  = -1;
        rc_bannerDraw = (rc_mode == MODE_INTRO || rc_mode == MODE_CLEAR);
    }
}


static void RC_RenderInner(void)
{
    if(rc_dirtyFull)
    {
        rc_dirtyFull = false;
        FullRepaint();
    }

    if(rc_mode == MODE_TITLE || rc_mode == MODE_HOWTO || rc_mode == MODE_LETTER)
    {
        rc_TitleRender();
        return;
    }

    if(rc_mode == MODE_CARDS)
    {
        rc_CardsRender();
        return;
    }

    if(rc_mode == MODE_INV)
    {
        rc_InventoryRender();
        return;
    }

    if(rc_mode == MODE_OVER || rc_mode == MODE_NAME || rc_mode == MODE_SCORES)
    {
        rc_OverRender();
        return;
    }

    if(rc_hud) rc_DrawHud();
    rc_DrawManaBar();

    if(rc_viewDirty)
    {
        rc_RenderView();
        rc_viewDirty--;
    }

    if(rc_mode == MODE_PLAY) rc_DrawCdStrip();

    if(rc_bannerDraw)
    {
        rc_DrawBanner();
        rc_bannerDraw = false;
    }
}


static void RC_Render(void)
{
    RC_RenderInner();
    PaceWait();
}


// After the pause overlay: repaint everything from the current state.
static void RC_Redraw(void)
{
    PaceInit();                                 // don't "catch up" after the pause
    rc_dirtyFull = true;
    if(rc_mode != MODE_OVER && rc_mode != MODE_NAME && rc_mode != MODE_SCORES &&
       rc_mode != MODE_TITLE && rc_mode != MODE_HOWTO && rc_mode != MODE_LETTER)
    {
        if(s_rcThemeOn) RcTheme_Start();                    // the pause menu interrupted the music
        else            Buzzer_PlaySong(&song_corridor_run, 1);
    }
}


static void RC_Exit(void)
{
    Buzzer_Stop();
    MP3_stop();
}


//*****************************************************************************
// The app descriptor: the ONLY public symbol in this file.
//*****************************************************************************
const App g_raycasterApp =
{
    "RAYCASTER",                            // name (first letter = menu tile icon)
    "Stick:move L/R:turn D:fire U:swap",    // hint shown under the menu
    COLOR_CRIMSON,                             // menu tile color
    RC_FRAME_US,
    RC_Init, RC_Update, RC_Render,
    RC_Exit,
    NULL,                                   // not a legacy app
    RC_Redraw
};
